class ExportBase(betterproto2_grpclib.ServiceBase):
    """
    ---------------------------------------------------------------------------
    The service (ADR 0029 §1, §2)
    ---------------------------------------------------------------------------

    Defined in M5 PR 4 and served from PR 7, for the reason Generate, Render, Preview and
    Assistant were each defined before anything served them: `buf breaking` runs on pull requests
    only, so a wire that grows across two of them is compared against a main that has already
    moved (docs/plan.md, M4 trap 4).
    """

    async def compile(self, message: "CompileRequest") -> "CompileResponse":
        """
        One compile, blocking for its length — a median of 21 s in the spike — bounded by core's
        five-minute wall clock, and one in flight per session. A fresh process serves exactly one of
        these and exits; on timeout, cancel or end of file its whole process group is killed
        (ADR 0029 §4). No progress stream: the bound is what says a build is too slow.
        """

        raise grpclib.GRPCError(grpclib.const.Status.UNIMPLEMENTED)

    async def __rpc_compile(
        self, stream: "grpclib.server.Stream[CompileRequest, CompileResponse]"
    ) -> None:
        request = await stream.recv_message()
        assert request is not None
        response = await self.compile(request)
        await stream.send_message(response)

    def __mapping__(self) -> "dict[str, grpclib.const.Handler]":
        return {
            "/escribass.export.v1.Export/Compile": grpclib.const.Handler(
                self.__rpc_compile,
                grpclib.const.Cardinality.UNARY_UNARY,
                CompileRequest,
                CompileResponse,
            ),
        }
